  const sellParts = trade.map((entry) => Math.max(-entry, 0));
  const directCost = cost(trade, checked.buy, checked.sell);
  const auxiliaryCost = dot(checked.buy, buyParts) + dot(checked.sell, sellParts);
  const budgetResidual = stableSum(weights) + directCost - wealth;
  const fullObjective = dot(checked.mean, weights) - checked.risk * quadratic(checked.sigma, weights) - directCost;
  const finalSmooth = smoothGradient(point, mean, sigma, checked.risk, wealth);
